"use strict";
import { useMemo } from "react";
import { useEthersProvider } from "hooks/useEthersProvider";
import { useAccount } from "hooks/useAccount";
import { getAbstractContracts } from "uniswap/src/constants/abstractContracts";
import NonfungiblePositionManagerJson from "@uniswap/v3-periphery/artifacts/contracts/NonfungiblePositionManager.sol/NonfungiblePositionManager.json";
import { getContract } from "utilities/src/contracts/getContract";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { validateTransactionRequest } from "uniswap/src/features/transactions/swap/utils/trade";
const { abi: NFTPositionManagerABI } = NonfungiblePositionManagerJson;
export function useAbstractCollectFees({
  tokenId,
  recipient,
  amount0Max,
  amount1Max,
  enabled = true
}) {
  const { chainId } = useAccount();
  const provider = useEthersProvider({ chainId });
  const contracts = getAbstractContracts(chainId || UniverseChainId.Sepolia);
  const txRequest = useMemo(() => {
    console.log("\u{1F527} [COLLECT FEES DEBUG] Hook inputs:", {
      enabled,
      tokenId,
      recipient,
      provider: !!provider,
      nftManager: contracts?.nonfungiblePositionManager,
      amount0Max,
      amount1Max
    });
    if (!enabled || !tokenId || !recipient || !provider || !contracts?.nonfungiblePositionManager) {
      console.log("\u274C [COLLECT FEES] Missing required parameters");
      return null;
    }
    try {
      const positionManager = getContract(
        contracts.nonfungiblePositionManager,
        NFTPositionManagerABI,
        provider
      );
      const finalAmount0Max = amount0Max || "340282366920938463463374607431768211455";
      const finalAmount1Max = amount1Max || "340282366920938463463374607431768211455";
      const collectParams = {
        tokenId,
        recipient,
        amount0Max: finalAmount0Max,
        amount1Max: finalAmount1Max
      };
      const calldata = positionManager.interface.encodeFunctionData("collect", [collectParams]);
      const txRequest2 = {
        to: contracts.nonfungiblePositionManager,
        data: calldata,
        value: "0",
        chainId: chainId || UniverseChainId.Sepolia,
        gasLimit: void 0
        // Let wallet estimate
      };
      const validatedRequest = validateTransactionRequest(txRequest2);
      console.log("\u2705 [COLLECT FEES] Generated transaction request:", {
        to: txRequest2.to,
        data: txRequest2.data,
        tokenId,
        recipient,
        amount0Max,
        amount1Max,
        validated: !!validatedRequest
      });
      return validatedRequest;
    } catch (error) {
      console.error("\u274C [COLLECT FEES] Error generating transaction:", error);
      return null;
    }
  }, [tokenId, recipient, amount0Max, amount1Max, provider, contracts, enabled]);
  const result = {
    data: txRequest ? { claim: txRequest } : null,
    isLoading: false,
    error: null,
    refetch: () => {
    }
    // No need to refetch static transaction data
  };
  console.log("\u{1F4E4} [COLLECT FEES] Hook result:", {
    hasData: !!result.data,
    hasClaim: !!result.data?.claim,
    isLoading: result.isLoading,
    error: result.error
  });
  return result;
}
